  const isComparison = ["cheaper", "more_expensive", "alternative"].includes(intent);
  let comparisonAnchor = null;
  if (isComparison) {
    if (requests.length !== 1 || !requests[0]?.category) {
      return invalidResult("Follow-up violation: exactly one target request is required.");
    }
    const target = requests[0];
    const matches = previous.filter(item => categoryKey(item?.category) === categoryKey(target.category));
    comparisonAnchor = matches.length === 1 ? matches[0] : null;
    const approvedAnchor = Object.prototype.hasOwnProperty.call(PRODUCT_CATALOG, comparisonAnchor?.recommended_product)
      ? PRODUCT_CATALOG[comparisonAnchor.recommended_product] : null;
    if (!approvedAnchor || categoryKey(approvedAnchor.category) !== categoryKey(target.category)
      || !Number.isFinite(comparisonAnchor.price) || comparisonAnchor.price !== approvedAnchor.price) {
      return invalidResult("Follow-up violation: a unique approved same-category historical recommendation is required.");
    }
    // A comparison must never bypass the existing hard cap through bad state.
    // General budget normalization and partial updates remain Phase 1B.2 work.
    const budget = Number(target.budget);
    if (!Number.isFinite(budget) || budget <= 0) {
      return invalidResult("Follow-up violation: a valid positive hard budget is required.");
    }
  }

  let validation_ok = true;
  let validation_error = "";

  const seenCategories = new Set();

  // Do not allow more recommendations than active product requests.
  if (recommendations.length > requests.length) {
    return invalidResult(
      "Validation violation: more recommendations were returned than active product requests."
    );
  }

  for (const rec of recommendations) {
    if (!rec || typeof rec !== "object") {
      validation_ok = false;
      validation_error =
        "Validation violation: recommendation must be an object.";
      break;
    }

    const productName =
      typeof rec.recommended_product === "string"
        ? rec.recommended_product.trim()
        : "";

    const recCategory =
      typeof rec.category === "string"
        ? rec.category.trim()
        : "";

    const recSource =
      typeof rec.source === "string"
        ? rec.source.trim()
        : "";

    const price = Number(rec.price);

    // 1. Product identity validation
    const approvedProduct = Object.prototype.hasOwnProperty.call(PRODUCT_CATALOG, productName)
      ? PRODUCT_CATALOG[productName] : null;

    if (!approvedProduct) {
      validation_ok = false;
      validation_error =
        `Product validation violation: "${productName || "Unknown product"}" ` +
        `is not an approved MyTech product.`;
      break;
    }

    // 2. Product-category validation
    if (
      approvedProduct.category.toLowerCase() !==
      recCategory.toLowerCase()
    ) {
      validation_ok = false;
      validation_error =
        `Category validation violation: "${productName}" is a ` +
        `${approvedProduct.category}, not a ${recCategory || "missing category"}.`;
      break;
    }

    // 3. Active-request category validation
    const request = requests.find(
      r =>
        String(r.category || "")
          .trim()
          .toLowerCase() ===
        approvedProduct.category.toLowerCase()
    );

    if (!request) {
      validation_ok = false;
      validation_error =
        `Category validation violation: "${productName}" belongs to ` +
        `${approvedProduct.category}, but there is no active request for that category.`;
      break;
    }

    // 4. Prevent duplicate recommendations for the same category
    const categoryKey =
      approvedProduct.category.toLowerCase();

    if (seenCategories.has(categoryKey)) {
      validation_ok = false;
      validation_error =
        `Validation violation: multiple recommendations were returned for ` +
        `${approvedProduct.category}.`;
      break;
    }

    seenCategories.add(categoryKey);

    // 5. Exact reference-price validation
    if (
      !Number.isFinite(price) ||
      price !== approvedProduct.price
    ) {
      validation_ok = false;
      validation_error =
        `Price validation violation: "${productName}" must use the approved ` +
        `reference price of ¥${approvedProduct.price}.`;
      break;
    }

    // 6. Exact source validation
    if (recSource !== approvedProduct.source) {
      validation_ok = false;
      validation_error =
        `Source validation violation: "${productName}" must use the approved ` +
        `source "${approvedProduct.source}".`;
      break;
    }

    // Check every recommendation, including initial turns, against Master Dataset usage tags.
    const usageCheck = checkCatalogueUsage(approvedProduct, request.main_usage, PRODUCT_CATALOG, USAGE_COMPATIBILITY);
    if (!usageCheck.valid) return invalidResult("Usage validation violation: " + usageCheck.error);

    // 7. Hard-budget validation
    const budget = Number(request.budget);

    if (
      Number.isFinite(budget) &&
      price > budget
    ) {
      validation_ok = false;
      validation_error =
        `Budget violation: ${productName} costs ¥${price}, ` +
        `but the active budget is ¥${budget}.`;
      break;
    }

    // Only the verified same-category anchor may drive this comparison.
    const previousRec = comparisonAnchor;

    // 8. Follow-up validation
    if (previousRec) {
      const previousPrice = Number(previousRec.price);

      if (
        intent === "cheaper" &&
        Number.isFinite(previousPrice) &&
        price >= previousPrice
      ) {
        validation_ok = false;
        validation_error =
          "Follow-up violation: cheaper recommendation must cost less than the previous recommendation.";
        break;
      }

      if (
        intent === "more_expensive" &&
        Number.isFinite(previousPrice) &&
        price <= previousPrice
      ) {
        validation_ok = false;
        validation_error =
          "Follow-up violation: more_expensive recommendation must cost more than the previous recommendation.";
        break;
      }

      if (
        intent === "alternative" &&
        productName.toLowerCase() ===
        String(previousRec.recommended_product || "")
          .trim()
          .toLowerCase()
      ) {
        validation_ok = false;
        validation_error =
          "Follow-up violation: alternative recommendation must be a different product.";
        break;
      }

      if (
        intent === "cheaper" ||
        intent === "more_expensive" ||
        intent === "alternative"
      ) {
        const previousCategory =
          String(previousRec.category || "")
            .trim()
            .toLowerCase();

        if (
          previousCategory &&
          previousCategory !==
            approvedProduct.category.toLowerCase()
        ) {
          validation_ok = false;
          validation_error =
            "Follow-up category violation: follow-up recommendations must remain in the same product category.";
          break;
        }
      }
    }
  }

  if (!validation_ok) return invalidResult(validation_error);

  // Empty public recommendations do not erase historical comparison anchors.
  // Successful comparisons update only their target; ordinary successful tasks
  // retain the baseline whole-response replacement/reset behavior.
  let recommendations_to_store = recommendations;
  if (recommendations.length === 0) {
    recommendations_to_store = previous.map(item => ({ ...item }));
    if (validation_ok && isComparison) {
      const target = requests[0];
      const comparisonLabel = intent === "more_expensive" ? "more expensive"
        : intent === "alternative" ? "alternative" : "cheaper";
      const article = intent === "alternative" ? "an" : "a";
      answer = "I couldn't find " + article + " " + comparisonLabel + " " + target.category
        + " for " + target.main_usage + " within RMB " + target.budget
        + " in the retrieved MyTech reference data.";
      next_step = "Would you like to adjust your " + target.category + " budget or usage?";
    }
  } else if (validation_ok && isComparison) {
    const targetKey = categoryKey(requests[0].category);
    recommendations_to_store = previous.map(item => categoryKey(item?.category) === targetKey
      ? { ...recommendations[0] } : { ...item });
  }

  const normalized = {
    answer,
    recommendations,
    next_step,
    clarification_needed
  };

  return {
    answer,
    recommendations,
    next_step,
    clarification_needed,
    validation_ok,
    validation_error,
    recommendations_to_store,
    normalized_json: JSON.stringify(normalized)
  };

  function invalidResult(message) {
    const safe = {
      answer: "I couldn't safely validate a recommendation for your requirements.",
      recommendations: [],
      next_step: "Please restate the category, maximum budget and main usage.",
      clarification_needed: true
    };
    return {
      ...safe,
      validation_ok: false,
      validation_error: message,
      // Current's validation router skips its writer on failure. Keep safe
      // memory output too, so rejected results cannot replace prior anchors.
      recommendations_to_store: Array.isArray(previous_recommendations)
        ? previous_recommendations.map(item => ({ ...item })) : [],
      normalized_json: JSON.stringify(safe)
    };
  }
}

